using Mbb.Archive.Modules.Retention.Application;
using Mbb.Archive.BuildingBlocks.Application;using Mbb.Archive.Modules.Retention.Application.Abstractions;using Mbb.Archive.Modules.Retention.Domain.Rules;namespace Mbb.Archive.Modules.Retention.Application.Rules.Create;public sealed class CreateRetentionRuleCommandHandler:ICommandHandler<CreateRetentionRuleCommand,Guid>{private readonly IRetentionRepository _repo;private readonly IUnitOfWork<RetentionBoundary> _uow;private readonly TimeProvider _time;public CreateRetentionRuleCommandHandler(IRetentionRepository repo,IUnitOfWork<RetentionBoundary> uow,TimeProvider time){_repo=repo;_uow=uow;_time=time;}public async Task<Result<Guid>> Handle(CreateRetentionRuleCommand c,CancellationToken ct){if(await _repo.GetRuleByCodeAsync(c.Code,ct) is not null)return Result<Guid>.Failure(Error.Conflict("retention.rule_exists","Retention rule code already exists."));var r=RetentionRule.Create(c.Code,c.Name,c.RetentionMonths,c.Action,_time.GetUtcNow());await _repo.AddRuleAsync(r,ct);await _uow.SaveChangesAsync(ct);return Result<Guid>.Success(r.Id);}}
